import{_ as a,c as s,o as n,ag as t}from"./chunks/framework.Vyheyqg9.js";const h=JSON.parse('{"title":"A bounded Node.js log analyzer","description":"","frontmatter":{},"headers":[],"relativePath":"practice/node-js/core-project.md","filePath":"practice/node-js/core-project.md"}'),r={name:"practice/node-js/core-project.md"};function i(o,e,l,d,c,p){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="a-bounded-node-js-log-analyzer" tabindex="-1">A bounded Node.js log analyzer <a class="header-anchor" href="#a-bounded-node-js-log-analyzer" aria-label="Permalink to “A bounded Node.js log analyzer”">​</a></h1><p><strong>Learner status: still required.</strong> This is the small runtime project that precedes the larger <a href="./../backend-project.html#p-332">P-332 failure lab</a>. It needs no Express, database, broker, cloud account or frontend.</p><h2 id="prerequisites-and-scope" tabindex="-1"><span class="hub-section-number">1 </span>Prerequisites and scope <a class="header-anchor" href="#prerequisites-and-scope" aria-label="Permalink to “1 Prerequisites and scope”">​</a></h2><p>Know JavaScript functions, scope, arrays/objects, promises and basic <code>try</code>/<code>catch</code>. Read Node Modules 1–3, the testing parts of Module 4 and raw HTTP/client parts of Module 5. Use runtime diagnostics from Module 11 and lifecycle principles from Module 10 as needed. Compile typed implementations with the chosen project&#39;s existing compiler; plain ESM JavaScript is also suitable in a new independent practice directory.</p><p>Build one CLI that reads a local NDJSON log file and returns a small summary. Then expose the same pure analysis behind a loopback HTTP endpoint. Reuse concepts from the <a href="./../../workbench/node-js/">runtime workbench</a>, but implement your application independently. A framework or persistence layer would obscure this project&#39;s runtime goals.</p><p>Each nonblank line is a JSON object with exactly <code>level</code> (<code>info</code>, <code>warn</code> or <code>error</code>) and <code>message</code> (a string of 1–200 characters). The source is synthetic and contains no credentials. Count records by level and return exactly <code>{total, info, warn, error}</code>; do not retain or echo message text. For the three records below, the summary is total 3, info 1, warn 0, error 2.</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;level&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;info&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;started&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;level&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dependency unavailable&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;level&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;request failed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="n-01-—-cli-modules-and-filesystem-ownership" tabindex="-1"><span class="hub-section-number">2 </span>N-01 — CLI, modules and filesystem ownership <a class="header-anchor" href="#n-01-—-cli-modules-and-filesystem-ownership" aria-label="Permalink to “2 N-01 — CLI, modules and filesystem ownership”">​</a></h2><p><strong>Scope:</strong> <code>node analyze.mjs &lt;input&gt; &lt;output&gt;</code> in an owned learner directory. Separate argument/config validation, analysis and the executable entry point. Importing the analysis module must not start work or open handles. Use explicit ESM markers; compare a tiny <code>.cjs</code> export in the separate module exercise.</p><p><strong>Acceptance:</strong> missing arguments produce a safe usage error and nonzero exit. Valid input produces the exact summary. Empty input produces four zero counts. Missing/unreadable input and malformed records fail with a safe category and line number. Output is published only after successful analysis; partial temporary output is removed on failure. An existing output is not silently overwritten unless an explicit replacement policy was chosen and tested. Close every file handle.</p><p><strong>Failure cases:</strong> nonexistent input, exclusive-output conflict, failed destination and invalid configuration. Explain exclusive creation versus replacement, atomic filename visibility versus crash durability, and why a CLI&#39;s authorized file path is not an HTTP caller&#39;s storage permission.</p><p><strong>Evidence:</strong> actual arguments with private paths redacted, stdout/stderr/exit code, resulting JSON, unchanged protected fixture and absence of leftover temporary files. Record the module format/runtime and output policy.</p><h2 id="n-02-—-incremental-bytes-framing-and-pressure" tabindex="-1"><span class="hub-section-number">3 </span>N-02 — Incremental bytes, framing and pressure <a class="header-anchor" href="#n-02-—-incremental-bytes-framing-and-pressure" aria-label="Permalink to “3 N-02 — Incremental bytes, framing and pressure”">​</a></h2><p><strong>Scope:</strong> stream input with at most 64 KiB chunks, 8 KiB per physical record, 10,000 nonblank records and 2 MiB total input. Validate the domain fields after parsing. Keep counters rather than an array of all records; apply limits before unbounded accumulation. Define LF/CRLF, blank-line and final-line policy explicitly, consistent with the textbook parser you select.</p><p><strong>Acceptance:</strong> the same UTF-8 data split at every byte boundary gives identical results. Invalid UTF-8, null/array/primitive records, unknown fields, invalid level/message, excessive record/chunk/count/total bytes reject. Include a slow consumer and demonstrate that production/pulls are governed by demand rather than an unbounded promise list. Do not report <code>highWaterMark</code> as a total memory ceiling.</p><p><strong>Failure cases:</strong> split multibyte characters, malformed later line, source read failure, destination failure and early consumer exit. All pipeline owners settle and release resources; failure cannot publish a successful final report.</p><p><strong>Evidence:</strong> fixed input bytes and split schedules, expected/observed errors and line numbers, pull/queue counts, input size and memory categories under a declared repeated workload. Tiny correctness fixtures establish contracts, not a universal memory benchmark.</p><h2 id="n-03-—-http-and-complete-operation-lifetimes" tabindex="-1"><span class="hub-section-number">4 </span>N-03 — HTTP and complete operation lifetimes <a class="header-anchor" href="#n-03-—-http-and-complete-operation-lifetimes" aria-label="Permalink to “4 N-03 — HTTP and complete operation lifetimes”">​</a></h2><p><strong>Scope:</strong> a raw <code>node:http</code> server bound to loopback. <code>POST /analyze</code> accepts the same NDJSON contract with an explicit media type; it never accepts a filesystem path or command. <code>GET /health/live</code> is shallow. Reuse the analysis function rather than create a second parser. Use ephemeral ports for automated checks.</p><p><strong>Acceptance:</strong> valid input returns 200 and the summary; malformed records return the documented 400 policy, unsupported media 415 and excessive bytes 413 when the transport still permits a response. Close rejected HTTP/1.x body connections under a deadline; an aborted peer is not guaranteed to receive JSON. No response exposes messages, stack traces, paths or request credentials. Header/body/idle limits and one complete-operation deadline are explicit.</p><p>Create an outbound client against an owned local server that sends headers promptly and delays the body. Prove the client deadline covers body consumption, HTTP error bodies are cancelled or safely consumed, malformed output rejects, and success passes runtime schema validation. Do not retry writes after an uncertain outcome.</p><p><strong>Failure cases:</strong> stalled body, client disconnect, invalid media, delayed upstream body, bad status/schema and failed bind. Stop the server and close owned agents/connections/timers after every case.</p><p><strong>Evidence:</strong> safe request/status/header/summary observations, failing schedules, cancellation reason, process exit and resource ownership. A Node client cannot prove browser CORS/cookie enforcement.</p><h2 id="n-04-—-cancellation-errors-and-bounded-concurrency" tabindex="-1"><span class="hub-section-number">5 </span>N-04 — Cancellation, errors and bounded concurrency <a class="header-anchor" href="#n-04-—-cancellation-errors-and-bounded-concurrency" aria-label="Permalink to “5 N-04 — Cancellation, errors and bounded concurrency”">​</a></h2><p><strong>Scope:</strong> add a batch of a few independent local-file analyses, with at most two active tasks and a declared item cap. Preserve input order. On first failure stop assigning new items, abort cooperative active work, wait for it to drain and preserve the original rejection. SIGINT requests cancellation through the entry-point owner.</p><p><strong>Acceptance:</strong> controllable promises prove two active tasks maximum, correct result order, zero calls for pre-abort/invalid/over-budget input and no new task after observed failure. Rejection with <code>undefined</code> is still failure. A successful output cannot be reported while a failed operation&#39;s peer is still writing. A noncooperative adapter needs its own deadline; abort is not rollback.</p><p><strong>Failure cases:</strong> one mapper fails while another is held, abort before launch and during read, and cleanup failure accompanying a primary error. Preserve both causes deliberately without exposing raw private data.</p><p><strong>Evidence:</strong> start/abort/drain sequence, effect counts and outcome identity. Use the chapter&#39;s focused worker/child exercises for CPU/process boundaries; a worker pool or thumbnail service is optional depth, not a prerequisite to this analyzer.</p><h2 id="n-05-—-meaningful-tests-and-diagnosis" tabindex="-1"><span class="hub-section-number">6 </span>N-05 — Meaningful tests and diagnosis <a class="header-anchor" href="#n-05-—-meaningful-tests-and-diagnosis" aria-label="Permalink to “6 N-05 — Meaningful tests and diagnosis”">​</a></h2><p><strong>Scope:</strong> verify the previous increments with focused pure checks, real temporary-file/HTTP integration and one deliberately broken baseline. Use the existing project runner. For an Autocode task retain its Jest/build scripts and restricted test directory; place independent practice checks only in an authorized location.</p><p><strong>Acceptance:</strong> an intentionally broken chunk parser, forgotten await or ignored failure makes a relevant check fail. Test a real open/read/write failure as well as adapter doubles. Diagnose one controlled event-loop stall using delay/utilization and a short CPU capture where justified; compare the same workload after bounding/removing the work. Diagnose an intentionally unclosed interval/server and remove the owner leak without forced successful exit.</p><p><strong>Failure cases:</strong> test passes alone but not together, unobserved rejection, timer left running and misleading average latency. Define a small workload and retain latency/error/memory observations without claiming production gains.</p><p><strong>Evidence:</strong> source revision, runtime/compiler/lock, actual commands and exit results, meaningful assertions and detected defect, safe diagnostic artifact and its limitations. Run every applicable build/test/coverage command and verify natural termination.</p><h2 id="n-06-—-shutdown-and-the-continuation-decision" tabindex="-1"><span class="hub-section-number">7 </span>N-06 — Shutdown and the continuation decision <a class="header-anchor" href="#n-06-—-shutdown-and-the-continuation-decision" aria-label="Permalink to “7 N-06 — Shutdown and the continuation decision”">​</a></h2><p><strong>Scope:</strong> mark the HTTP service unready, stop admission, drain or cancel bounded active analyses, release streams/files/clients, and finish before an external process deadline. Share one shutdown outcome across repeated calls. Test forced termination only in a disposable child process.</p><p><strong>Acceptance:</strong> held work has an explicit completion/cancellation policy; new work is denied; resource close occurs after its last user; cleanup failure yields a nonzero outcome. A stuck owner reaches the final deadline rather than a fabricated successful exit. Inspector/profiling ports are never exposed publicly.</p><p><strong>Evidence:</strong> shutdown sequence, readiness/admission observations, effect/output state, exit code and remaining handles. Explain which operations are request-bound and which would require durable jobs.</p><p>After this project, P-332 deepens runtime failures. Choose P-331 only when adding an authenticated Express/PostgreSQL service is the next learning goal. P-333 concerns a later deployed service; MongoDB, Redis, WebSocket, GraphQL, brokers and cloud platforms remain requirement-driven alternatives.</p>`,38)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
